/* ===========================================================================
 * Pocket Dungeon 2.0 — game data
 * Transcribed from "Pocket Dungeon 2.0" (revision by Matt Mason; original by
 * Jonathan Gilmour). This is reference content for running the system; all
 * rules text is paraphrased into structured data for play.
 * =========================================================================== */

const GAME = {};

/* ---------- Races -------------------------------------------------------- */
// mods applied AFTER the player distributes 9 points (max 5 per attribute).
// `choice` races let the player pick which attribute gets the +1.
GAME.races = [
  { id: "human",    name: "Human",    blurb: "the base race",          mods: {},                                  maxhp: 0,  note: "No modifications." },
  { id: "elf",      name: "Elf",      blurb: "the noble forestral race", mods: { choice: { amt: 1, of: ["agi", "wil"] } }, maxhp: -3, note: "+1 Agility or Willpower, -3 Max HP." },
  { id: "halfelf",  name: "Half Elf", blurb: "the versatile race",     mods: {},                                  maxhp: -3, note: "+1 additional Fudge Point per 10 monsters defeated, -3 Max HP.", extraFudgePer10: true },
  { id: "dwarf",    name: "Dwarf",    blurb: "the stalwart race",      mods: { agi: -1 },                         maxhp: 3,  note: "+3 Max HP, -1 Agility." },
  { id: "gnome",    name: "Gnome",    blurb: "the tinkering race",     mods: { str: -1, choice: { amt: 1, of: ["agi", "wil"] } }, maxhp: -3, note: "+1 Bonus Rating at start of every dungeon, +1 Agi or Wil, -3 Max HP, -1 Str.", startBonusRating: 1 },
  { id: "halfling", name: "Halfling", blurb: "the nimble race",        mods: { agi: 1, str: -1 },                 maxhp: 0,  note: "+1 Agility, -1 Strength." },
  { id: "halforc",  name: "Half Orc", blurb: "the brutish race",       mods: { str: 1, wil: -2 },                 maxhp: 3,  note: "+1 Strength, +3 Max HP, -2 Willpower." },
];

/* ---------- Professions -------------------------------------------------- */
// hpBase: Max HP = hpBase + (best of 2d6) + race maxhp mod
// spells: max memorized (0 = no spells). scrolls: may use scrolls.
GAME.professions = [
  {
    id: "warrior", name: "Warrior", hpBase: 10, rec: "Strength", spells: 0, scrolls: false,
    desc: "A heavily armed combatant who relies on weapons, armor, and combat abilities.",
    restrictions: ["May not use spells or scrolls", "May use all armor, shields, and weapons"],
    abilities: [
      { name: "Bash", ap: 1, text: "Roll d6 (+1 per 3 Strength). Open a locked door/chest on 5+." },
      { name: "Drive Back", ap: 1, text: "Roll d6 (+1 per 3 Strength). On 5+, push all monsters from an adjacent square 1 square and move into it." },
      { name: "Precision Strike", ap: 1, text: "Your attack(s) this round get +2H and -1D." },
      { name: "Knockdown", ap: 1, text: "Knock one adjacent opponent down; it takes no action this round. Not usable on bosses." },
      { name: "Whirlwind", ap: 4, text: "Attack all adjacent enemies. Single combat roll vs the highest-Def adjacent enemy; if it hits, all are hit." },
      { name: "Battle Cry", ap: 2, text: "All monsters attacking you get +1 penalty to Attack rolls for the rest of combat." },
      { name: "Flurry of Blows", ap: 4, text: "Make twice your normal number of attacks this turn." },
    ],
  },
  {
    id: "wizard", name: "Wizard", hpBase: 6, rec: "Willpower", spells: 3, scrolls: true,
    desc: "An expert in magecraft and the art of spellcasting.",
    restrictions: ["Up to 3 spells memorized", "Only cloth armor and Mithril Armor", "No shields", "Only 1-handed weapons and the Archmage's Staff"],
    abilities: [
      { name: "Dark Rituals", ap: 0, text: "Sacrifice 4 HP to recover 4 AP." },
      { name: "Spell Recall", ap: 1, text: "Swap one memorized spell with one from your spell book during combat." },
      { name: "Empower Spell", ap: "varies", text: "+1 damage to your next spell per 2 AP spent." },
      { name: "Heighten Spell", ap: 1, text: "Double the Range or the Hit value of your next spell." },
      { name: "Ethereal Link", ap: 4, text: "Regenerate 2 AP at the end of each combat round. Ends if you do anything but cast spells." },
      { name: "Ethereal Shield", ap: 4, text: "Block 1 successful attack from a single monster, ignoring all damage and effects." },
      { name: "Ethereal Mist", ap: 4, text: "All monsters attacking you get +1 penalty to Attack rolls for the rest of combat." },
    ],
  },
  {
    id: "thief", name: "Thief", hpBase: 8, rec: "Agility", spells: 0, scrolls: true,
    desc: "An agile rogue specializing in blades, stealth, and bypassing locks & traps.",
    restrictions: ["No spells; may use scrolls", "Only cloth, leather, and Mithril Armor", "Only buckler shields", "Only 1-handed weapons, Bladed Bracers, bows and Elven Bows"],
    abilities: [
      { name: "Pick Lock", ap: 1, text: "Roll d6 (+1 per 3 Agility). Open a locked door/chest on 5+." },
      { name: "Disarm Trap", ap: 1, text: "Roll d6 (+1 per 3 Agility). Remove a trap from a door/chest on 5+." },
      { name: "Sneak", ap: 1, text: "At start of combat, try to pass a room unnoticed. Roll d6 (+1 per 3 Agility) per monster whose LOS you pass; 5+ succeeds. Ends on attacking or leaving." },
      { name: "Blinding Dust", ap: 1, text: "One adjacent enemy gets +1 penalty to all Attack rolls for the rest of combat." },
      { name: "Tumble", ap: 3, text: "Roll d6 (+1 per 3 Agility). On 5+, dodge any 1 successful attack from a single monster." },
      { name: "Blade Flurry", ap: 3, text: "Attack each adjacent enemy with your normal number of attacks. Requires sword, dagger, or Bladed Bracers." },
      { name: "Backstab", ap: 2, text: "If Sneak is active and you hit an adjacent enemy, deal double damage. Requires sword, dagger, or Bladed Bracers. Ends Sneak." },
    ],
  },
  {
    id: "ranger", name: "Ranger", hpBase: 8, rec: "Agility & Willpower", spells: 1, scrolls: true,
    desc: "A combatant skilled in ranged attacks, spellcasting, and controlling the field of combat.",
    restrictions: ["1 spell memorized", "Only cloth, leather, and Mithril Armor", "Only buckler and heater shields", "Only 1-handed weapons, bows and Elven Bows"],
    abilities: [
      { name: "Quick Strike", ap: 1, text: "Conduct a move and an attack this round." },
      { name: "Aimed Shot", ap: 1, text: "Your attack(s) this round get +2 Hit. Requires a bow or Elven Bow." },
      { name: "Strider's Legs", ap: 1, text: "+2 Movement for the rest of the turn." },
      { name: "Cripple", ap: 1, text: "Target's Move is halved. If already 1, it may only move every other turn." },
      { name: "Set Trap", ap: 2, text: "Set a spike trap in an adjacent square; monsters avoid it or take 2 damage. Lasts until end of combat." },
      { name: "Triple Shot", ap: 3, text: "Make 3 attacks this round, each at -1 to the combat roll. Requires a bow or Elven Bow." },
      { name: "Focused Speed", ap: 4, text: "Double your Agility for the rest of the turn." },
    ],
  },
  {
    id: "cleric", name: "Cleric", hpBase: 8, rec: "Strength & Willpower", spells: 0, scrolls: true,
    desc: "A champion relying on blunt weapons, heavy armor, and divine abilities.",
    restrictions: ["No spells; may use scrolls", "May use all armor and shields", "Only hammer, mace, and warhammer"],
    abilities: [
      { name: "Heal", ap: 4, text: "Restore 1 HP." },
      { name: "Ward of Protection", ap: 4, text: "Ignore all damage and effects from a single monster's successful attack." },
      { name: "Divination", ap: 2, text: "Roll on the Treasure Type table for a chest before opening it; you may reroll once but must accept the result." },
      { name: "Radiance", ap: 4, text: "Roll d6 (+1 per 3 Str & Wil). 6+: undead/supernatural retreat 1 square. 8+: one is slain too. Not vs bosses." },
      { name: "Smite", ap: 2, text: "Your attack this round gets +2 Hit and +1 damage." },
      { name: "Prayer", ap: 0, text: "If the Cleric takes no actions this round, restore 1 AP per 3 points of Str & Wil." },
    ],
  },
  {
    id: "monk", name: "Monk", hpBase: 8, rec: "Balance of Str, Agi & Wil", spells: 0, scrolls: true,
    desc: "An unarmed warrior who uses Ki abilities to defend and attack.",
    restrictions: ["No spells; may use scrolls", "Only cloth armor and Mithril Armor", "No shields", "No weapons"],
    abilities: [
      { name: "Ki Defense", ap: 0, text: "+1 Armor per 3 Agi & Wil while wearing only cloth armor (Mithril dispels this)." },
      { name: "Unarmed Combat", ap: 0, text: "One unarmed attack per round (R1 H1 D1). Attack skill is the greater of Agility or Strength." },
      { name: "Ki Strike", ap: 0, text: "When unarmed, gain +1 Hit and +1 damage per 3 Str & Wil." },
      { name: "Ki Speed", ap: 1, text: "+2 Movement for 1 round." },
      { name: "Serpent's Stance", ap: 4, text: "Double your Agility for the rest of the turn." },
      { name: "Mountain Stance", ap: 4, text: "Double your Strength for the rest of the turn." },
      { name: "Fist and Foot", ap: 4, text: "Unarmed/Ki Strike attack against each adjacent monster (separate combat roll each)." },
    ],
  },
  {
    id: "barbarian", name: "Barbarian", hpBase: 10, rec: "Strength & Agility", spells: 0, scrolls: false,
    desc: "A combatant using heavy weapons and light armor for devastating attacks.",
    restrictions: ["No spells or scrolls", "Only cloth, leather, and Mithril Armor", "May use all shields", "May use all weapons"],
    abilities: [
      { name: "Swath of Destruction", ap: 0, text: "With a Battle Axe, Warhammer, Pike, or Dwarven Axehammer: +1 Armor per 3 Agility." },
      { name: "Mighty Blow", ap: 0, text: "With a Strength-skill weapon: +1 damage per 3 Strength." },
      { name: "Fury", ap: 1, text: "Your attack(s) this round get +2 Hit. Requires a Strength-skill weapon." },
      { name: "Berzerker", ap: 0, text: "+1 Str & +1 Agi per 1 HP sacrificed. Resets at end of combat; HP lost until healed." },
      { name: "Back Swing", ap: 2, text: "With an R1 weapon, make a second attack on the same target (new combat roll)." },
      { name: "Bash", ap: 1, text: "Roll d6 (+1 per 3 Strength). Open a locked door/chest on 5+." },
    ],
  },
];

/* ---------- Weapons (W table, d8) ---------------------------------------- */
GAME.weapons = [
  { roll: 1, name: "Hammer",      R: 1, D: 2, H: 0, hnd: 1, skill: "str", strReq: 3 },
  { roll: 2, name: "Sword",       R: 1, D: 2, H: 0, hnd: 1, skill: "str", strReq: 3 },
  { roll: 3, name: "Dagger",      R: 1, D: 1, H: 1, hnd: 1, skill: "agi", strReq: 0 },
  { roll: 4, name: "Battle Axe",  R: 1, D: 3, H: 0, hnd: 2, skill: "str", strReq: 5 },
  { roll: 5, name: "Bow",         R: 4, D: 2, H: 0, hnd: 2, skill: "agi", strReq: 0 },
  { roll: 6, name: "Mace",        R: 1, D: 2, H: 0, hnd: 1, skill: "str", strReq: 3 },
  { roll: 7, name: "Warhammer",   R: 1, D: 3, H: 0, hnd: 2, skill: "str", strReq: 5 },
  { roll: 8, name: "Pike",        R: 2, D: 2, H: 0, hnd: 2, skill: "str", strReq: 5 },
];

/* ---------- Exotic Weapons (XW table, d6) -------------------------------- */
GAME.exoticWeapons = [
  { roll: 1, name: "Bladed Bracers",   R: 1, D: 1, H: 1, hnd: 2, skill: "agi", strReq: 0, note: "Attack twice; if both hit, +1D each." },
  { roll: 2, name: "Double Glaive",    R: 1, D: 1, H: 1, hnd: 2, skill: "str", strReq: 3, note: "Attack twice; if both hit, +1D each." },
  { roll: 3, name: "Whip",             R: 2, D: 1, H: 0, hnd: 1, skill: "str", strReq: 3 },
  { roll: 4, name: "Elven Bow",        R: 4, D: 3, H: 1, hnd: 2, skill: "agi", strReq: 0 },
  { roll: 5, name: "Dwarven Axehammer", R: 1, D: 3, H: 2, hnd: 2, skill: "str", strReq: 5 },
  { roll: 6, name: "Wand",             R: 3, D: 1, H: 1, hnd: 1, skill: "wil", strReq: 0 },
];

/* ---------- Armor & Shields (A table, d6) -------------------------------- */
GAME.armor = [
  { roll: 1, name: "Cloth Armor",    A: 0, type: "armor",  strReq: 0 },
  { roll: 2, name: "Leather Armor",  A: 1, type: "armor",  strReq: 3 },
  { roll: 3, name: "Platemail Armor", A: 2, type: "armor", strReq: 5 },
  { roll: 4, name: "Buckler Shield", A: 0, type: "shield", strReq: 0 },
  { roll: 5, name: "Heater Shield",  A: 1, type: "shield", strReq: 3 },
  { roll: 6, name: "Tower Shield",   A: 2, type: "shield", strReq: 5 },
];

/* ---------- Potions (P table, d8) ---------------------------------------- */
GAME.potions = [
  { roll: "1-2", name: "Potion of Healing",      text: "Heal 4 HP." },
  { roll: "3-4", name: "Potion of Restoration",  text: "Restore AP to maximum." },
  { roll: "5",   name: "Vial of Acid",           text: "Open any 1 locked door or treasure chest." },
  { roll: "6",   name: "Potion of Ignite",       text: "Thrown to R3: automatically deal D3 to a single enemy." },
  { roll: "7",   name: "Potion of Explodify",    text: "Thrown to R3: D3 to all enemies in target square, D2 to each adjacent creature (incl. you!)." },
  { roll: "8",   name: "Unstable Potion",        text: "Quaff & roll d6: 1 +1Str, 2 +1Agi, 3 +1Wil, 4 +3 Max HP, 5 nothing, 6 -1 highest attribute." },
];

/* ---------- Scrolls (S table, d8) ---------------------------------------- */
GAME.scrolls = [
  { roll: "1",   name: "Scroll of Innervate",   text: "+1 to each attribute (Str, Agi, Wil) for 5 turns." },
  { roll: "2",   name: "Scroll of Stoneskin",   text: "+1 Armor and +3 Max HP for 5 turns." },
  { roll: "3",   name: "Scroll of Healing",     text: "Restore up to 8 HP." },
  { roll: "4-5", name: "Spell Scroll",          text: "Add any spell from the Spells table to your spell book." },
  { roll: "6",   name: "Scroll of Dark Energy", text: "Black beam hits all monsters in a line from caster (R5 D4). Auto-hits." },
  { roll: "7",   name: "Scroll of Arcane Blast", text: "Blasts all monsters in the room (D3). Auto-hits." },
  { roll: "8",   name: "Scroll of Ball Lightning", text: "Lightning ball hits 1 monster (R1 D5). Auto-hits." },
];

/* ---------- Magic Items (MI table, d8) ----------------------------------- */
GAME.magicItems = [
  { roll: "1", name: "Mithril Armor",      text: "2A. Any profession, no Strength requirement.", A: 2, type: "armor" },
  { roll: "2", name: "Lucky Coin",         text: "Adjust any die roll: roll d6, 4-6 = ±1. Once per roll. 5 uses then disintegrates.", uses: 5 },
  { roll: "3", name: "Spell book page",    text: "Add any 2 spells from the Spells table to your spell book, then it turns to dust." },
  { roll: "4", name: "Archmage's Staff",   text: "Weapon R1 D1 H1 2Hnd, skill Willpower. Memorize +1 spell while equipped.", R: 1, D: 1, H: 1, hnd: 2, skill: "wil" },
  { roll: "5", name: "Boots of Striding",  text: "+1 Movement while worn." },
  { roll: "6", name: "Blinking Stone",     text: "Teleport to the most recently explored room. 3 uses then vanishes.", uses: 3 },
  { roll: "7", name: "Skeleton Key",       text: "Open one locked door or chest per use. 5 uses then shatters.", uses: 5 },
  { roll: "8", name: "Amulet of Shielding", text: "Absorbs unmitigated damage. After 5 HP absorbed, vanishes.", uses: 5 },
];

/* ---------- Spells ------------------------------------------------------- */
// combat: requires a combat roll (attack skill Willpower) and has R/D/H.
GAME.spells = [
  { name: "Blink",          ap: 3,        combat: false, text: "Teleport to the most recently explored room." },
  { name: "Enchant Weapon", ap: 2,        combat: false, text: "Equipped weapon gains +2H, or +2D, or +1H/+1D until end of combat. Stacks." },
  { name: "Enfeeble",       ap: 2, R: 2, D: 0, H: 0, combat: false, text: "Target monster deals 1 less damage for the rest of combat. Stacks." },
  { name: "Enwizen",        ap: "varies", combat: false, text: "+1 Willpower per 1 AP spent (no AP gained from the boost) until end of turn." },
  { name: "Fear",           ap: 2, R: 2, D: 0, H: 0, combat: false, text: "Target monster moves away from you for 3 rounds." },
  { name: "Fireball",       ap: 3, R: 2, D: 4, H: 0, combat: true,  text: "Targets highest-Def enemy in a square; if it hits, damages all monsters in that square." },
  { name: "Frost Bolt",     ap: 2, R: 4, D: 2, H: 0, combat: true,  text: "Hits all monsters in a straight line (range 4). Roll vs highest-Def target." },
  { name: "Haste",          ap: 3,        combat: false, text: "+2 Movement for 1 turn. In combat, conduct 3 actions next round." },
  { name: "Knock",          ap: 1, R: 1,  combat: false, text: "Unlock a door or chest." },
  { name: "Life Drain",     ap: "varies", R: 1, D: 1, H: 0, combat: true, text: "Drain 1 HP from a monster and heal 1 HP per 2 AP spent. Bonus Rating boosts damage only." },
  { name: "Magic Missile",  ap: 1, R: 5, D: 1, H: 1, combat: true,  text: "Two missiles; same or separate targets. Combat roll each." },
  { name: "Quicken",        ap: "varies", combat: false, text: "+1 Agility per 1 AP spent until end of turn." },
  { name: "Shocking Grasp", ap: 1, R: 1, D: 3, H: 0, combat: true,  text: "Electrical damage to a single adjacent monster." },
  { name: "Strengthen",     ap: "varies", combat: false, text: "+1 Strength per 1 AP spent until end of turn." },
  { name: "Tangle",         ap: 2, R: 4, D: 0, H: 0, combat: false, text: "Hold 1 target monster in place; it cannot move for 3 rounds." },
];

/* ---------- DUN-GEN tables ----------------------------------------------- */
// Each entry: roll value -> result. Sizes/doors use d6; monsters/treasure d8.
GAME.dungen = {
  size:     { die: 6, table: [{ max: 2, val: 4 }, { max: 3, val: 5 }, { max: 5, val: 6 }, { max: 6, val: 7 }] },
  doors:    { die: 6, table: [{ max: 2, val: 1 }, { max: 5, val: 2 }, { max: 6, val: 3 }] },
  monsters: { die: 8, table: [{ max: 1, val: 0 }, { max: 3, val: 1 }, { max: 5, val: 2 }, { max: 7, val: 3 }, { max: 8, val: 4 }] },
  treasure: { die: 8, table: [{ max: 2, val: 0 }, { max: 5, val: 1 }, { max: 7, val: 2 }, { max: 8, val: "SR" }] },
  // Locks & Traps: rolled per door beyond the first, and per chest. d6.
  locks:    { die: 6, table: [{ max: 3, val: "Unlocked" }, { max: 5, val: "Locked" }, { max: 6, val: "Trapped" }] },
};

GAME.specialRooms = {
  die: 6,
  table: [
    { roll: 1, name: "Healing Font",     text: "After combat, drink to restore HP to max. Returnable (3 uses total)." },
    { roll: 2, name: "Altar of Blessing", text: "After combat, use once to gain +1 Bonus Rating." },
    { roll: 3, name: "Armory",           text: "After combat, roll once each on Weapon, Armor, and Exotic Weapon tables." },
    { roll: 4, name: "Alchemy Lab",      text: "After combat, roll 3 times on the Potion table." },
    { roll: 5, name: "Library",          text: "After combat, roll 3 times on the Scroll table." },
    { roll: 6, name: "Arcane Forge",     text: "After combat, roll twice on the Magic Item table." },
  ],
};

/* ---------- Treasure Type table (d8) ------------------------------------- */
GAME.treasureType = {
  die: 8,
  table: [
    { max: 2, type: "W",  label: "Weapon" },
    { max: 3, type: "XW", label: "Exotic Weapon" },
    { max: 5, type: "A",  label: "Armor & Shield" },
    { max: 6, type: "P",  label: "Potion" },
    { max: 7, type: "S",  label: "Scroll" },
    { max: 8, type: "MI", label: "Magic Item" },
  ],
};

/* ---------- Selling price chart ------------------------------------------ */
GAME.sellRules = {
  weaponNote: "Gold = sum of R + D + H. +5 if exotic, +10 if magic item, +2 per aspect.",
  armorNote: "Gold = 3× the (A) value. +2 per aspect.",
  potion: 1, scroll: 3, trinket: 2,
};

/* ---------- Monster Manual ----------------------------------------------- */
// Each package: { tier, theme, name, monsters: [ {minion stats...} x3, boss] }
// Monster stats: Def, HP, R(ange), M(ove), att:[lo,hi] (d6 hit range), D(amage), special
const m = (name, Def, HP, R, M, att, D, special) =>
  ({ name, Def, HP, R, M, att, D, special: special || "" });

GAME.monsterManual = [
  /* ---- TIER 1 ---- */
  { tier: 1, theme: "Humanoids", monsters: [
    m("Kobolds", 9, 3, 1, 2, [1,2], 2),
    m("Goblins", 10, 4, 1, 1, [1,2], 3),
    m("Hobgoblins", 11, 6, 1, 1, [1,2], 4),
    m("Ragnar the Ogre (Boss)", 13, 12, 1, 2, [1,2], 5, "On attack roll 3-4, boulder throw (R3 D6)."),
  ]},
  { tier: 1, theme: "Undead", monsters: [
    m("Skeletons", 9, 3, 1, 2, [1,2], 2),
    m("Zombies", 10, 4, 1, 1, [1,2], 3),
    m("Ghouls", 11, 6, 1, 1, [1,2], 4),
    m("Arkanos the Lich (Boss)", 12, 12, 3, 1, [1,2], 5, "On attack roll 3-4, summons an undead minion adjacent (d6: 1-2 Skeleton, 3-4 Zombie, 5-6 Ghoul)."),
  ]},
  { tier: 1, theme: "Cult", monsters: [
    m("Cultist", 9, 3, 1, 1, [1,2], 2),
    m("Fanatic", 10, 4, 1, 2, [1,2], 3),
    m("Dread Priest", 11, 6, 1, 1, [1,2], 4),
    m("Mozozar the Summoner (Boss)", 12, 12, 3, 1, [1,2], 5, "On attack roll 3-4, summons an Imp adjacent (Imp: Def10 HP5 R1 M3 Att1-3 D3)."),
  ]},
  { tier: 1, theme: "Beast", monsters: [
    m("Giant Rat", 9, 3, 1, 2, [1,2], 2),
    m("Acidic Slime", 2, 8, 1, 1, [1,3], 1, "On attack roll 4, splits into 2 slimes, each with ½ (round up) HP. Slimes ignore stacking; multiple may be adjacent to you."),
    m("Owl Bear", 11, 6, 1, 1, [1,2], 4),
    m("Water Elemental (Boss)", 13, 12, 2, 1, [1,2], 5, "On attack roll 3-4, casts ice bolt (R4 D6)."),
  ]},
  { tier: 1, theme: "Plumbing the Depths", monsters: [
    m("Darklings", 9, 3, 1, 2, [1,2], 2),
    m("Drow", 10, 4, 1, 1, [1,2], 3),
    m("Drow Lords", 11, 6, 1, 1, [1,2], 4),
    m("Lieutenant Stythe (Boss)", 13, 12, 1, 1, [1,2], 5, "On attack roll 3-4, hurls a poisoned obsidian blade (R3 D6)."),
  ]},

  /* ---- TIER 2 ---- */
  { tier: 2, theme: "Humanoids", monsters: [
    m("Kobold Skirmishers", 11, 6, 1, 2, [1,2], 4, "Add +2 to any # Monsters result of 1 or more."),
    m("Orcs", 12, 8, 1, 1, [1,2], 5),
    m("Orc Archers", 13, 8, 4, 2, [1,2], 4),
    m("Murke the Troll (Boss)", 16, 18, 1, 2, [1,3], 5, "Two claw attacks (Att1-3 D5 each). Regenerates d6÷2 (round up) HP before each round."),
  ]},
  { tier: 2, theme: "Undead", monsters: [
    m("Skeletal Archers", 11, 6, 4, 2, [1,2], 4),
    m("Wights", 12, 8, 1, 1, [1,2], 5, "On hit, Death's Chill Touch: hero cannot heal HP by any means until combat ends."),
    m("Nosferatu", 13, 8, 1, 2, [1,2], 6, "Add +2 to any # Monsters result of 1 or more."),
    m("Straud the Vampire (Boss)", 16, 18, 1, 2, [1,3], 4, "On hit, drains +1 additional HP and heals itself the same. The drain accumulates with each hit."),
  ]},
  { tier: 2, theme: "Beast", monsters: [
