"""
Pocket Dungeon — local Flask app for running the Pocket Dungeon 2.0 system
digitally (solo dungeon crawl by Jonathan Gilmour, rev. Matt Mason).

The whole game runs client-side; this server only serves the SPA and persists a
roster of heroes (each storing the hero sheet + current dungeon state as a JSON
blob) in a local SQLite DB so you can resume mid-dungeon and carry a hero across
dungeons/tiers.
"""
import json
import os
import sqlite3
import time

from flask import Flask, g, jsonify, request, send_from_directory

PORT = 5009
BASE = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.path.join(BASE, "pocket_dungeon.db")

app = Flask(__name__, static_folder="static", template_folder="templates")


# ---------------------------------------------------------------- database ---
def get_db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(_exc):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute(
        """
        CREATE TABLE IF NOT EXISTS heroes (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            name       TEXT NOT NULL,
            data       TEXT NOT NULL,          -- full hero + dungeon JSON blob
            created_at REAL NOT NULL,
            updated_at REAL NOT NULL
        )
        """
    )
    db.commit()
    db.close()


# ------------------------------------------------------------------ routes ---
@app.route("/")
def index():
    return send_from_directory("templates", "index.html")


@app.route("/static/<path:path>")
def static_files(path):
    return send_from_directory("static", path)


@app.route("/api/health")
def health():
    return jsonify(ok=True)


@app.route("/api/heroes", methods=["GET"])
def list_heroes():
    rows = get_db().execute(
        "SELECT id, name, data, updated_at FROM heroes ORDER BY updated_at DESC"
    ).fetchall()
    out = []
    for r in rows:
        blob = json.loads(r["data"])
        hero = blob.get("hero", {})
        dungeon = blob.get("dungeon") or {}
        out.append({
            "id": r["id"],
            "name": r["name"],
            "race": hero.get("raceName", ""),
            "profession": hero.get("professionName", ""),
            "tier": dungeon.get("tier", hero.get("tier", 1)),
            "roomsExplored": dungeon.get("roomsExplored", 0),
            "inDungeon": bool(dungeon.get("active")),
            "dead": bool(hero.get("dead")),
            "updated_at": r["updated_at"],
        })
    return jsonify(out)


@app.route("/api/heroes", methods=["POST"])
def create_hero():
    blob = request.get_json(force=True)
    name = (blob.get("hero", {}) or {}).get("name") or "Unnamed Hero"
    now = time.time()
    db = get_db()
    cur = db.execute(
        "INSERT INTO heroes (name, data, created_at, updated_at) VALUES (?,?,?,?)",
        (name, json.dumps(blob), now, now),
    )
    db.commit()
    return jsonify(id=cur.lastrowid)


@app.route("/api/heroes/<int:hid>", methods=["GET"])
def get_hero(hid):
    row = get_db().execute("SELECT data FROM heroes WHERE id=?", (hid,)).fetchone()
    if not row:
        return jsonify(error="not found"), 404
    return jsonify(json.loads(row["data"]))


@app.route("/api/heroes/<int:hid>", methods=["PUT"])
def update_hero(hid):
    blob = request.get_json(force=True)
    name = (blob.get("hero", {}) or {}).get("name") or "Unnamed Hero"
    db = get_db()
    db.execute(
        "UPDATE heroes SET name=?, data=?, updated_at=? WHERE id=?",
        (name, json.dumps(blob), time.time(), hid),
    )
    db.commit()
    return jsonify(ok=True)


@app.route("/api/heroes/<int:hid>", methods=["DELETE"])
def delete_hero(hid):
    db = get_db()
    db.execute("DELETE FROM heroes WHERE id=?", (hid,))
    db.commit()
    return jsonify(ok=True)


def start_background():
    """Hook matching the other desktop apps; nothing to schedule here."""
    init_db()


if __name__ == "__main__":
    init_db()
    print(f"Pocket Dungeon running at http://127.0.0.1:{PORT}/")
    app.run(host="127.0.0.1", port=PORT, debug=True, threaded=True, use_reloader=True)

