/* ===========================================================================
 * Pocket Dungeon — SPA logic & UI
 * =========================================================================== */
"use strict";
const G = window.GAME;

/* ----------------------------------------------------------------- state -- */
let state = null;        // { id, hero, dungeon }
let view = "roster";     // roster | play | reference
let saveTimer = null;
let paintTool = "floor";
let refTab = "monsters";

const $ = (sel, root = document) => root.querySelector(sel);
const el = (tag, props = {}, ...kids) => {
  const n = document.createElement(tag);
  for (const [k, v] of Object.entries(props)) {
    if (k === "class") n.className = v;
    else if (k === "html") n.innerHTML = v;
    else if (k.startsWith("on") && typeof v === "function") n.addEventListener(k.slice(2), v);
    else if (v !== null && v !== undefined) n.setAttribute(k, v);
  }
  for (const kid of kids.flat()) {
    if (kid == null) continue;
    n.appendChild(typeof kid === "string" ? document.createTextNode(kid) : kid);
  }
  return n;
};

/* ------------------------------------------------------------- utilities -- */
const roll = (sides) => Math.floor(Math.random() * sides) + 1;
const rollBest2 = (sides) => Math.max(roll(sides), roll(sides));
const ceilHalf = (n) => Math.max(1, Math.ceil(n / 2));
function tableLookup(spec, value) {        // spec = {die, table:[{max,val}]}
  for (const row of spec.table) if (value <= row.max) return row.val;
  return spec.table[spec.table.length - 1].val;
}
function deriveMovement(h) { return ceilHalf(h.agi); }
function deriveMaxAP(h) { return 2 * h.wil; }

/* --------------------------------------------------------------- logging -- */
function logMsg(msg, cls = "") {
  if (!state?.dungeon) return;
  state.dungeon.log = state.dungeon.log || [];
  state.dungeon.log.unshift({ t: msg, c: cls });
  if (state.dungeon.log.length > 200) state.dungeon.log.pop();
  renderLog();
  scheduleSave();
}
function renderLog() {
  const box = $("#log");
  if (!box) return;
  box.innerHTML = "";
  (state?.dungeon?.log || []).forEach((e) =>
    box.appendChild(el("div", { class: "entry " + (e.c || "") }, e.t)));
}

/* ----------------------------------------------------------- persistence -- */
async function api(method, path, body) {
  const res = await fetch(path, {
    method,
    headers: body ? { "Content-Type": "application/json" } : {},
    body: body ? JSON.stringify(body) : undefined,
  });
  if (!res.ok) throw new Error(res.status);
  return res.status === 200 ? res.json() : null;
}
function scheduleSave() {
  setSaveState("saving…");
  clearTimeout(saveTimer);
  saveTimer = setTimeout(saveNow, 600);
}
async function saveNow() {
  if (!state) return;
  try {
    if (state.id == null) {
      const r = await api("POST", "/api/heroes", { hero: state.hero, dungeon: state.dungeon });
      state.id = r.id;
    } else {
      await api("PUT", `/api/heroes/${state.id}`, { hero: state.hero, dungeon: state.dungeon });
    }
    setSaveState("saved ✓");
  } catch (e) { setSaveState("save failed"); }
}
function setSaveState(txt) { const s = $("#saveState"); if (s) s.textContent = txt; }

/* =========================================================================
 * NAV / ROUTER
 * ========================================================================= */
function renderNav() {
  const nav = $("#nav");
  nav.innerHTML = "";
  const tabs = [["roster", "Heroes"]];
  if (state) tabs.push(["play", "Play"]);
  tabs.push(["reference", "Rulebook"]);
  tabs.forEach(([id, label]) => {
    nav.appendChild(el("button", {
      class: view === id ? "active" : "",
      onclick: () => { view = id; render(); },
    }, label));
  });
  $("#dock").classList.toggle("hidden", !(state && view === "play"));
}

function render() {
  renderNav();
  const root = $("#app");
  root.innerHTML = "";
  if (view === "roster") renderRoster(root);
  else if (view === "play") renderPlay(root);
  else if (view === "reference") renderReference(root);
  if (view === "play") renderLog();
}

/* =========================================================================
 * ROSTER
 * ========================================================================= */
async function renderRoster(root) {
  root.appendChild(el("div", { class: "btn-row", style: "margin-bottom:18px" },
    el("button", { class: "btn primary", onclick: openCreator }, "+ New Hero")));

  let heroes = [];
  try { heroes = await api("GET", "/api/heroes"); } catch (e) {}

  if (!heroes.length) {
    root.appendChild(el("div", { class: "empty" },
      "No heroes yet. Create one to begin delving."));
    return;
  }
  heroes.forEach((h) => {
    const tags = [];
    if (h.dead) tags.push(el("span", { class: "tag-dead" }, "💀 fallen"));
    else if (h.inDungeon) tags.push(el("span", { class: "tag-active" }, `▸ in dungeon · room ${h.roomsExplored}`));
    root.appendChild(el("div", { class: "hero-card" + (h.dead ? " dead" : "") },
      el("div", { class: "avatar" }, h.dead ? "💀" : "🛡️"),
      el("div", { class: "grow" },
        el("div", { class: "name" }, h.name),
        el("div", { class: "muted" }, `${h.race} ${h.profession}  ·  `,
          el("span", { class: "tier-badge" }, `Tier ${h.tier}`), "  ", ...tags)),
      el("div", { class: "btn-row" },
        el("button", { class: "btn primary sm", onclick: () => loadHero(h.id) }, h.dead ? "View" : "Play"),
        el("button", { class: "btn danger sm", onclick: () => deleteHero(h.id, h.name) }, "Delete"))));
  });
}

async function loadHero(id) {
  const blob = await api("GET", `/api/heroes/${id}`);
  state = { id, hero: blob.hero, dungeon: blob.dungeon || null };
  view = "play";
  render();
}
async function deleteHero(id, name) {
  if (!confirm(`Delete ${name}? This cannot be undone.`)) return;
  await api("DELETE", `/api/heroes/${id}`);
  if (state && state.id === id) state = null;
  render();
}

/* =========================================================================
 * HERO CREATION
 * ========================================================================= */
function openCreator() {
  const draft = {
    name: "", raceId: "human", professionId: "warrior",
    str: 3, agi: 3, wil: 3, raceChoice: "agi",
  };
  showModal(() => creatorBody(draft));
}

function creatorBody(d) {
  const race = G.races.find((r) => r.id === d.raceId);
  const prof = G.professions.find((p) => p.id === d.professionId);
  const used = d.str + d.agi + d.wil;
  const left = 9 - used;

  // preview final attributes after race mods
  const finals = applyRaceMods(d);
  const valid = left === 0 && finals.ok;

  const attrRow = (key, label) => el("div", { class: "attr-row" },
    el("span", { class: "nm" }, label),
    el("div", { class: "stepper" },
      el("button", { onclick: () => { if (d[key] > 0) { d[key]--; refreshModal(() => creatorBody(d)); } } }, "−"),
      el("span", { class: "val" }, String(d[key])),
      el("button", { onclick: () => { if (d[key] < 5 && left > 0) { d[key]++; refreshModal(() => creatorBody(d)); } } }, "+")),
    el("span", { class: "muted" }, `→ final ${finals[key]}`));

  const body = el("div", {},
    el("h2", {}, "Create Your Hero"),
    el("label", {}, "Name"),
    el("input", { type: "text", value: d.name, placeholder: "Thornwick…",
      oninput: (e) => { d.name = e.target.value; } }),

    el("label", {}, "Race"),
    el("select", { onchange: (e) => { d.raceId = e.target.value; refreshModal(() => creatorBody(d)); } },
      ...G.races.map((r) => el("option", { value: r.id, ...(r.id === d.raceId ? { selected: "" } : {}) },
        `${r.name} — ${r.blurb}`))),
    el("div", { class: "note" }, race.note),
    raceChoiceField(d, race),

    el("label", {}, `Attributes — distribute 9 points (max 5 each).  `,
      el("span", { class: "points-left" }, `${left} left`)),
    attrRow("str", "Strength"),
    attrRow("agi", "Agility"),
    attrRow("wil", "Willpower"),
    el("div", { class: "note" }, "Strength → weapons/armor & melee. Agility → ranged & movement. Willpower → spells & Action Points."),

    el("label", {}, "Profession"),
    el("select", { onchange: (e) => { d.professionId = e.target.value; refreshModal(() => creatorBody(d)); } },
      ...G.professions.map((p) => el("option", { value: p.id, ...(p.id === d.professionId ? { selected: "" } : {}) }, p.name))),
    el("div", { class: "note" }, `${prof.desc}  Recommended: ${prof.rec}.`),
    el("div", { class: "note" }, "Restrictions: " + prof.restrictions.join("; ") + "."),

    el("div", { class: "gen-result", style: "margin-top:14px" },
      el("div", {}, el("span", { class: "k" }, "Movement: "), String(deriveMovement(finals)),
        "   ", el("span", { class: "k" }, "Max AP: "), String(deriveMaxAP(finals))),
      el("div", {}, el("span", { class: "k" }, "Max HP: "),
        `${prof.hpBase} + (best of 2d6)` + (race.maxhp ? ` ${race.maxhp >= 0 ? "+" : ""}${race.maxhp} (race)` : "") + " — rolled on confirm")),

    finals.ok ? null : el("div", { class: "note", style: "color:var(--blood2)" },
      "Race penalties push an attribute below 0 — raise it before continuing."),

    el("div", { class: "btn-row" },
      el("button", { class: "btn", onclick: closeModal }, "Cancel"),
      el("button", { class: "btn primary", disabled: valid && d.name ? null : "",
        onclick: () => finishCreate(d) }, "Roll HP & Begin")),
  );
  return body;
}

function raceChoiceField(d, race) {
  if (!race.mods.choice) return null;
  return el("div", {},
    el("label", {}, `Apply this race's +${race.mods.choice.amt} to:`),
    el("select", { onchange: (e) => { d.raceChoice = e.target.value; refreshModal(() => creatorBody(d)); } },
      ...race.mods.choice.of.map((a) => el("option", {
        value: a, ...(a === d.raceChoice ? { selected: "" } : {}),
      }, a === "agi" ? "Agility" : "Willpower"))));
}

function applyRaceMods(d) {
  const race = G.races.find((r) => r.id === d.raceId);
  const f = { str: d.str, agi: d.agi, wil: d.wil };
  for (const [k, v] of Object.entries(race.mods)) {
    if (k === "choice") f[d.raceChoice] += v.amt;
    else f[k] += v;
  }
  f.ok = f.str >= 0 && f.agi >= 0 && f.wil >= 0;
  return f;
}

function finishCreate(d) {
  const race = G.races.find((r) => r.id === d.raceId);
  const prof = G.professions.find((p) => p.id === d.professionId);
  const f = applyRaceMods(d);
  const hpRoll = rollBest2(6);
  const maxhp = prof.hpBase + hpRoll + race.maxhp;

  const hero = {
    name: d.name.trim() || "Unnamed Hero",
    raceId: race.id, raceName: race.name,
    professionId: prof.id, professionName: prof.name,
    str: f.str, agi: f.agi, wil: f.wil,
    maxhp, hp: maxhp,
    gold: 0, bonusRating: race.startBonusRating || 0, fudgePoints: 0,
    monstersSlainTotal: 0, tier: 1,
    equipped: { weapon: null, armor: { name: "Cloth Armor", A: 0, type: "armor" }, shield: null },
    inventory: [
      { kind: "potion", name: "Potion of Healing", text: "Heal 4 HP." },
      { kind: "potion", name: "Potion of Healing", text: "Heal 4 HP." },
    ],
    spellbook: [], memorized: [],
    dead: false,
  };
  hero.maxap = deriveMaxAP(hero);
  hero.ap = hero.maxap;
  hero.movement = deriveMovement(hero);

  state = { id: null, hero, dungeon: null };
  closeModal();
  saveNow();
  // pick starting loadout
  startingLoadout(prof);
}

/* ----- choose starting weapon or spells ----- */
function startingLoadout(prof) {
  const caster = prof.spells > 0;
  let pick = { weapon: G.weapons[1].name, spells: [] };
  showModal(() => {
    const body = el("div", {},
      el("h2", {}, "Starting Trappings"),
      el("div", { class: "note" }, "You begin with Cloth Armor and 2 Potions of Healing. " +
        (caster ? "Choose a weapon, or 2 starting spells." : "Choose a starting weapon.")),
      el("label", {}, "Weapon"),
      el("select", { id: "startWeapon" },
        el("option", { value: "" }, caster ? "— none (take spells instead) —" : "— choose —"),
        ...G.weapons.map((w) => el("option", { value: w.name },
          `${w.name}  (R${w.R} D${w.D} H${w.H}, ${w.hnd}Hnd, ${skillName(w.skill)}${w.strReq ? `, needs ${w.strReq} Str` : ""})`))),
    );
    if (caster) {
      body.appendChild(el("label", {}, `Or pick 2 spells (max ${prof.spells} memorized at a time):`));
      const sb = el("div", {});
