          state.hero.spellbook = [...pick.spells];
          state.hero.memorized = pick.spells.slice(0, prof.spells);
        }
        closeModal();
        startDungeonPrompt();
      } }, "Continue")));
    return body;
  });
}

const skillName = (s) => ({ str: "Str", agi: "Agi", wil: "Wil" }[s] || s);
const apLabel = (ap) => (ap === "varies" ? "varies" : ap);

/* =========================================================================
 * DUNGEON LIFECYCLE
 * ========================================================================= */
function packagesForTier(tier) {
  const t = Math.min(3, tier);
  return G.monsterManual.filter((p) => p.tier === t);
}

function startDungeonPrompt() {
  const tier = state.hero.tier || 1;
  const pkgs = packagesForTier(tier);
  let chosen = 0;
  showModal(() => el("div", {},
    el("h2", {}, `Enter a Tier ${tier} Dungeon`),
    el("div", { class: "note" }, "Choose the monster package that will inhabit this dungeon. " +
      "Monsters 1-3 fill rooms 1-9 / 10-19 / 20-29; the boss waits in room 30."),
    el("label", {}, "Monster package"),
    el("select", { onchange: (e) => { chosen = +e.target.value; } },
      ...pkgs.map((p, i) => el("option", { value: i }, `${p.theme} — ${p.monsters.map((m) => m.name.replace(/ \(Boss\)/, "")).join(", ")}`))),
    el("div", { class: "btn-row" },
      el("button", { class: "btn", onclick: closeModal }, "Cancel"),
      el("button", { class: "btn primary", onclick: () => beginDungeon(pkgs[chosen]) }, "Descend"))));
}

function beginDungeon(pkg) {
  if (state.hero.startBonusRatingApplied !== undefined) {}
  // gnome bonus rating at start of every dungeon
  const race = G.races.find((r) => r.id === state.hero.raceId);
  if (race.startBonusRating) state.hero.bonusRating += race.startBonusRating;

  const W = 13, H = 15;
  const cells = {};
  const entranceKey = `${H - 1},${Math.floor(W / 2)}`;
  cells[entranceKey] = "door";
  state.dungeon = {
    active: true, tier: state.hero.tier || 1,
    theme: pkg.theme, package: JSON.parse(JSON.stringify(pkg)),
    roomsExplored: 0, monstersSlainDungeon: 0,
    currentRoom: null, inCombat: false, round: 0,
    map: { w: W, h: H, cells },
    log: [],
  };
  // restore AP/HP at dungeon start
  state.hero.ap = state.hero.maxap;
  closeModal();
  logMsg(`Entered a Tier ${state.dungeon.tier} dungeon: ${pkg.theme}.`, "gold");
  view = "play";
  render();
  saveNow();
}

function monsterForRoom(roomsExplored) {
  // roomsExplored is count BEFORE entering the new room → new room index = +1
  const roomNum = roomsExplored + 1;
  const pk = state.dungeon.package.monsters;
  if (roomNum >= 30) return { mon: pk[3], boss: true };
  if (roomNum >= 20) return { mon: pk[2], boss: false };
  if (roomNum >= 10) return { mon: pk[1], boss: false };
  return { mon: pk[0], boss: false };
}

/* ----- DUN-GEN: generate the next room ----- */
function generateRoom() {
  const d = state.dungeon;
  if (d.currentRoom && !d.currentRoom.finished) {
    if (!confirm("Finish/abandon the current room first? Generating a new room discards the current one.")) return;
  }
  const roomNum = d.roomsExplored + 1;
  const isBossRoom = roomNum >= 30;

  const size = tableLookup(G.dungen.size, roll(6));
  const doors = tableLookup(G.dungen.doors, roll(6));
  // locks for doors beyond the first (entry + 1 always unlocked)
  const doorStatuses = [];
  for (let i = 0; i < doors; i++) {
    if (i === 0) doorStatuses.push("Unlocked");          // one extra always unlocked
    else doorStatuses.push(tableLookup(G.dungen.locks, roll(6)));
  }

  // monsters
  let monsterCount;
  const { mon, boss } = monsterForRoom(d.roomsExplored);
  if (isBossRoom) monsterCount = 1;
  else {
    monsterCount = tableLookup(G.dungen.monsters, roll(8));
    if (mon.special && /\+2 to any # Monsters result of 1 or more/.test(mon.special) && monsterCount >= 1)
      monsterCount += 2;
  }

  // treasure
  let chestCount = 0, special = null;
  if (!isBossRoom) {
    const tr = tableLookup(G.dungen.treasure, roll(8));
    if (tr === "SR") { special = G.specialRooms.table[roll(6) - 1]; chestCount = 0; }
    else chestCount = tr;
  }
  const chestStatuses = [];
  for (let i = 0; i < chestCount; i++) chestStatuses.push(tableLookup(G.dungen.locks, roll(6)));

  // build monster instances
  const monsters = [];
  for (let i = 0; i < monsterCount; i++) {
    monsters.push({
      ...mon, id: i, hpMax: mon.HP, hp: mon.HP, boss,
      label: monsterCount > 1 ? `${baseName(mon.name)} ${String.fromCharCode(65 + i)}` : baseName(mon.name),
    });
  }

  d.currentRoom = {
    roomNum, size, doors, doorStatuses, special,
    chests: chestStatuses.map((s, i) => ({ status: s, opened: false, id: i })),
    monsters, isBossRoom, finished: false, looted: false,
  };
  d.inCombat = monsters.length > 0;
  d.round = monsters.length > 0 ? 1 : 0;

  logMsg(`Room ${roomNum}: size ${size}, ${doors} extra door(s)` +
    (monsters.length ? `, ${monsters.length} ${baseName(mon.name)}${monsters.length > 1 ? "s" : ""}` : ", empty") +
    (special ? `, Special Room: ${special.name}` : (chestCount ? `, ${chestCount} chest(s)` : "")) + ".", "gold");
  render();
  saveNow();
}
const baseName = (n) => n.replace(/ \(Boss\)/, "");

/* ----- finishing a room ----- */
function finishRoom() {
  const d = state.dungeon, r = d.currentRoom;
  r.finished = true;
  d.inCombat = false;
  d.roomsExplored += 1;

  // Bonus Rating: +1 per 5 rooms explored
  const newBR = Math.floor(d.roomsExplored / 5) + (G.races.find(x=>x.id===state.hero.raceId).startBonusRating ? 0 : 0);
  // (BR from rooms is recomputed against a baseline; track explicitly)
  recomputeBonusRating();

  // restore AP by Willpower
  const before = state.hero.ap;
  state.hero.ap = Math.min(state.hero.maxap, state.hero.ap + state.hero.wil);
  logMsg(`Room ${r.roomNum} explored. Restored ${state.hero.ap - before} AP (Willpower).`, "");

  if (r.isBossRoom && r.monsters.every((m) => m.hp <= 0)) {
    return winDungeon();
  }
  render();
  saveNow();
}

function recomputeBonusRating() {
  // 1 per 5 rooms + gnome start bonuses already added to base. We store
  // hero.bonusRating as the live total; rooms contribute floor(rooms/5).
  const d = state.dungeon;
  const roomsBR = Math.floor(d.roomsExplored / 5);
  state.hero.bonusRating = (state.hero.bonusRatingBase || 0) + roomsBR;
}

/* =========================================================================
 * COMBAT
 * ========================================================================= */
function heroAttack(monster) {
  const h = state.hero;
  const w = h.equipped.weapon;
  if (!w) { alert("No weapon equipped. Equip one, or use a spell from the play panel."); return; }
  const skillVal = h[w.skill];
  const r = roll(6);
  const total = r + skillVal + (w.H || 0) + (w.brH || 0);
  const dmg = (w.D || 0) + (w.brD || 0);
  if (total >= monster.Def) {
    monster.hp -= dmg;
    logMsg(`${w.name}: d6=${r} +${skillName(w.skill)}${skillVal} +H${(w.H||0)+(w.brH||0)} = ${total} vs Def${monster.Def} — HIT, ${dmg} dmg to ${monster.label}.`, "hit");
    if (monster.hp <= 0) killMonster(monster);
  } else {
    logMsg(`${w.name}: d6=${r} +${skillName(w.skill)}${skillVal} +H${(w.H||0)+(w.brH||0)} = ${total} vs Def${monster.Def} — miss on ${monster.label}.`, "miss");
  }
  render();
  saveNow();
}

function castCombatSpell(spellName, monster) {
  const h = state.hero;
  const s = G.spells.find((x) => x.name === spellName);
  const r = roll(6);
  const total = r + h.wil + (s.H || 0);
  const dmg = (s.D || 0) + (s.brD || 0);
  if (total >= monster.Def) {
    monster.hp -= dmg;
    logMsg(`${s.name}: d6=${r} +Wil${h.wil} +H${s.H||0} = ${total} vs Def${monster.Def} — HIT, ${dmg} dmg to ${monster.label}.`, "hit");
    if (monster.hp <= 0) killMonster(monster);
  } else {
    logMsg(`${s.name}: d6=${r} +Wil${h.wil} +H${s.H||0} = ${total} vs Def${monster.Def} — miss on ${monster.label}.`, "miss");
  }
  render();
  saveNow();
}

function killMonster(monster) {
  monster.hp = 0;
  state.dungeon.monstersSlainDungeon += 1;
  state.hero.monstersSlainTotal += 1;
  // fudge points: 1 per 5 monsters (+half-elf bonus handled at +1 per 10)
  recomputeFudge();
  logMsg(`${monster.label} is slain!`, "gold");
}

function recomputeFudge() {
  const total = state.hero.monstersSlainTotal;
  let fp = Math.floor(total / 5);
  const race = G.races.find((r) => r.id === state.hero.raceId);
  if (race.extraFudgePer10) fp += Math.floor(total / 10);
  state.hero.fudgePoints = fp - (state.hero.fudgeSpent || 0);
}

function monstersAttack() {
  const d = state.dungeon, h = state.hero;
  const alive = d.currentRoom.monsters.filter((m) => m.hp > 0);
  if (!alive.length) { alert("No monsters left to attack."); return; }
  let totalDmg = 0;
  const lines = [];
  alive.forEach((mon) => {
    const r = roll(6);
    const hit = r >= mon.att[0] && r <= mon.att[1];
    if (hit) { totalDmg += mon.D; lines.push(`${mon.label} d6=${r} HIT (${mon.D})`); }
    else lines.push(`${mon.label} d6=${r} miss`);
  });
  const armor = heroArmorValue();
  const net = Math.max(0, totalDmg - armor);
  h.hp -= net;
  logMsg(`Monsters attack: ${lines.join("; ")}. Total ${totalDmg} − ${armor} armor = ${net} damage.`,
    net > 0 ? "miss" : "hit");
  d.round += 1;
  if (h.hp <= 0) { h.hp = 0; return heroDies(); }
  render();
  saveNow();
}

function heroArmorValue() {
  const h = state.hero;
  let a = (h.equipped.armor?.A || 0) + (h.equipped.armor?.brA || 0);
  a += (h.equipped.shield?.A || 0) + (h.equipped.shield?.brA || 0);
  return a;
}

function heroDies() {
  state.hero.dead = true;
  state.dungeon.active = false;
  logMsg("Your hero has fallen. The dungeon claims another soul. ☠", "miss");
  render();
  saveNow();
  setTimeout(() => alert(`${state.hero.name} has died in the dungeon.\n\nRooms explored: ${state.dungeon.roomsExplored}\nMonsters slain (lifetime): ${state.hero.monstersSlainTotal}`), 100);
}

function winDungeon() {
  const d = state.dungeon;
  logMsg(`The boss is slain! Tier ${d.tier} dungeon cleared after ${d.roomsExplored} rooms. 🏆`, "gold");
  d.active = false;
  render();
  saveNow();
  setTimeout(() => betweenDungeons(), 150);
}

/* =========================================================================
 * TREASURE
 * ========================================================================= */
function rollTreasureItem() {
  const type = tableLookup(G.treasureType, roll(8));
  let item = null, label = "";
  if (type === "W") { const w = G.weapons[roll(8) - 1]; item = { kind: "weapon", ...w }; label = w.name; }
  else if (type === "XW") { const w = G.exoticWeapons[roll(6) - 1]; item = { kind: "weapon", exotic: true, ...w }; label = w.name; }
  else if (type === "A") { const a = G.armor[roll(6) - 1]; item = { kind: a.type, ...a }; label = a.name; }
  else if (type === "P") { const p = pickByRange(G.potions, roll(8)); item = { kind: "potion", name: p.name, text: p.text }; label = p.name; }
  else if (type === "S") { const s = pickByRange(G.scrolls, roll(8)); item = { kind: "scroll", name: s.name, text: s.text }; label = s.name; }
  else if (type === "MI") { const mi = pickByRange(G.magicItems, roll(8)); item = { kind: "magic", name: mi.name, text: mi.text, ...mi }; label = mi.name; }

  applyBonusRating(item);
  state.hero.inventory.push(item);
  logMsg(`Found: ${label}${brSuffix(item)}.`, "gold");
  render();
  saveNow();
}

function pickByRange(list, r) {
  for (const row of list) {
    const parts = String(row.roll).split("-").map(Number);
    const lo = parts[0], hi = parts.length > 1 ? parts[1] : parts[0];
    if (r >= lo && r <= hi) return row;
  }
  return list[list.length - 1];
}

function applyBonusRating(item) {
  const br = state.hero.bonusRating || 0;
  if (!br || !item) return;
  if (item.kind === "weapon") { item.brD = br; item.brBy = br; }          // default: BR → damage
  else if (item.kind === "armor" || item.kind === "shield") {
    item.brA = Math.floor(br / 3); item.brBy = br;
  }
}
function brSuffix(item) {
  if (item?.brBy) return ` (Bonus Rating ${item.brBy} applied${item.brD ? `: +${item.brD}D` : item.brA ? `: +${item.brA}A` : ""})`;
  return "";
}

/* =========================================================================
 * BETWEEN DUNGEONS  (sell / upgrade / advance tier)
 * ========================================================================= */
function betweenDungeons() {
  view = "play";
  render();
}

function sellItem(idx) {
  const it = state.hero.inventory[idx];
  let gold = 0;
  if (it.kind === "weapon") gold = (it.R || 0) + (it.D || 0) + (it.H || 0) + (it.exotic ? 5 : 0) + (it.kind === "magic" ? 10 : 0);
  else if (it.kind === "armor" || it.kind === "shield") gold = 3 * (it.A || 0);
  else if (it.kind === "potion") gold = 1;
  else if (it.kind === "scroll") gold = 3;
  else if (it.kind === "magic") gold = 2 + 10;
  state.hero.gold += gold;
  state.hero.inventory.splice(idx, 1);
  logMsg(`Sold ${it.name} for ${gold} gold.`, "gold");
  render(); saveNow();
}

function advanceTier() {
  if (!confirm(`Begin a Tier ${(state.hero.tier || 1) + 1} dungeon? Your hero carries over.`)) return;
  state.hero.tier = (state.hero.tier || 1) + 1;
  startDungeonPrompt();
}

/* =========================================================================
 * PLAY VIEW
 * ========================================================================= */
function renderPlay(root) {
  const h = state.hero;
  recomputeBonusRating();
  if (h.dead) {
    root.appendChild(el("div", { class: "panel" },
      el("h2", {}, "💀 Fallen Hero"),
      el("div", {}, `${h.name} died in the dungeon.`),
      el("div", { class: "btn-row" },
        el("button", { class: "btn", onclick: () => { view = "roster"; render(); } }, "Back to roster"))));
    root.appendChild(heroPanel());
    return;
  }
  const wrap = el("div", { class: "row" });
  wrap.appendChild(el("div", { class: "col", style: "flex:1.1" }, heroPanel()));
  wrap.appendChild(el("div", { class: "col", style: "flex:1.4" }, dungeonPanel(), mapPanel()));
  root.appendChild(wrap);
}

/* ----- hero panel ----- */
function heroPanel() {
  const h = state.hero;
  h.movement = deriveMovement(h);
  h.maxap = deriveMaxAP(h);
  const p = el("div", { class: "panel" });
  p.appendChild(el("h2", {}, `🛡️ ${h.name}`));
  p.appendChild(el("div", { class: "muted", style: "margin-top:-6px;margin-bottom:10px" },
    `${h.raceName} ${h.professionName} · `, el("span", { class: "tier-badge" }, `Tier ${h.tier}`)));

  // HP / AP bars
  p.appendChild(barCtrl("HP", "hp", h.hp, h.maxhp, (v) => { h.hp = clamp(v, 0, h.maxhp); if (h.hp <= 0 && state.dungeon?.active) heroDies(); else { render(); saveNow(); } }));
  p.appendChild(barCtrl("AP", "ap", h.ap, h.maxap, (v) => { h.ap = clamp(v, 0, h.maxap); render(); saveNow(); }));

  // core stats
  p.appendChild(el("div", { class: "statgrid", style: "margin-top:10px" },
    stat("STR", h.str), stat("AGI", h.agi), stat("WIL", h.wil),
    stat("Move", h.movement), stat("Armor", heroArmorValue()), stat("Gold", h.gold)));
  p.appendChild(el("div", { class: "statgrid", style: "margin-top:8px" },
    stat("Bonus Rating", h.bonusRating), stat("Fudge Pts", h.fudgePoints), stat("Slain", h.monstersSlainTotal)));

  // fudge / quick adjust
  p.appendChild(el("div", { class: "btn-row", style: "margin-top:10px" },
    el("button", { class: "btn sm", onclick: openFudge, disabled: h.fudgePoints > 0 ? null : "" }, "Spend Fudge Points")));

  // equipped
  p.appendChild(el("h3", {}, "Equipped"));
  p.appendChild(el("ul", { class: "itemlist" },
    equipRow("Weapon", h.equipped.weapon),
    equipRow("Armor", h.equipped.armor),
    equipRow("Shield", h.equipped.shield)));

  // spells
  const prof = G.professions.find((x) => x.id === h.professionId);
  if (prof.spells > 0) {
    p.appendChild(el("h3", {}, `Spells (memorize ≤ ${prof.spells})`));
    p.appendChild(spellSection(prof));
  }

  // inventory
  p.appendChild(el("h3", {}, "Inventory"));
  p.appendChild(inventorySection());

  return p;
}

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }
function stat(k, v) { return el("div", { class: "stat" }, el("div", { class: "v" }, String(v)), el("div", { class: "k" }, k)); }

function barCtrl(label, cls, cur, max, onset) {
  const pct = max > 0 ? Math.max(0, Math.min(100, (cur / max) * 100)) : 0;
  return el("div", {},
    el("label", { style: "margin-bottom:2px" }, label),
    el("div", { class: "bar" }, el("div", { class: "fill " + cls, style: `width:${pct}%` }),
      el("div", { class: "lbl" }, `${cur} / ${max}`)),
    el("div", { class: "hp-ctrl" },
      el("button", { class: "btn sm", onclick: () => onset(cur - 1) }, "−1"),
      el("button", { class: "btn sm", onclick: () => onset(cur + 1) }, "+1"),
      el("input", { type: "number", value: cur, onchange: (e) => onset(parseInt(e.target.value || "0", 10)) }),
      label === "HP"
        ? el("button", { class: "btn sm", onclick: () => onset(max) }, "full")
        : el("button", { class: "btn sm", onclick: () => onset(max) }, "full")));
}

function equipRow(slot, item) {
  if (!item) return el("li", {}, el("span", { class: "grow muted" }, `${slot}: —`));
  return el("li", {},
    el("span", { class: "grow" }, el("strong", {}, item.name),
      el("span", { class: "sub" }, "  " + itemStatLine(item))),
    slot !== "Armor" || item.name !== "Cloth Armor"
      ? el("button", { class: "btn sm", onclick: () => { unequip(slot); } }, "unequip")
      : null);
}

function unequip(slot) {
  const h = state.hero;
  const key = slot.toLowerCase();
  if (h.equipped[key]) { h.inventory.push(h.equipped[key]); h.equipped[key] = null; render(); saveNow(); }
}

function itemStatLine(it) {
  if (it.kind === "weapon") return `R${it.R} D${it.D}${it.brD ? "+" + it.brD : ""} H${it.H}${it.brH ? "+" + it.brH : ""} ${it.hnd}Hnd ${skillName(it.skill)}`;
  if (it.kind === "armor" || it.kind === "shield") return `${it.A + (it.brA || 0)}A`;
  return it.text || "";
}

function inventorySection() {
  const h = state.hero;
  if (!h.inventory.length) return el("div", { class: "note" }, "Empty.");
  const ul = el("ul", { class: "itemlist" });
  h.inventory.forEach((it, idx) => {
    const actions = el("span", { class: "btn-row" });
    if (it.kind === "weapon") actions.appendChild(el("button", { class: "btn sm", onclick: () => equip(idx, "weapon") }, "equip"));
    if (it.kind === "armor") actions.appendChild(el("button", { class: "btn sm", onclick: () => equip(idx, "armor") }, "equip"));
    if (it.kind === "shield") actions.appendChild(el("button", { class: "btn sm", onclick: () => equip(idx, "shield") }, "equip"));
    if (it.kind === "potion") actions.appendChild(el("button", { class: "btn sm", onclick: () => usePotion(idx) }, "use"));
    if (it.kind === "scroll") actions.appendChild(el("button", { class: "btn sm", onclick: () => useConsumable(idx, "Used") }, "use"));
    if (it.kind === "magic" && /Spell book page|Spell Scroll/.test(it.name)) {} // handled manually
    actions.appendChild(el("button", { class: "btn sm danger", onclick: () => { state.hero.inventory.splice(idx, 1); render(); saveNow(); } }, "drop"));
    ul.appendChild(el("li", {},
      el("span", { class: "grow" }, it.name, el("span", { class: "sub" }, "  " + (itemStatLine(it) || ""))),
      actions));
  });
  return ul;
}

function equip(idx, slot) {
  const h = state.hero, it = h.inventory[idx];
  if (h.equipped[slot]) h.inventory.push(h.equipped[slot]);
  h.equipped[slot] = it;
  h.inventory.splice(idx, 1);
  // 2-handed weapon clears shield
  if (slot === "weapon" && it.hnd === 2 && h.equipped.shield) {
    h.inventory.push(h.equipped.shield); h.equipped.shield = null;
  }
  const req = it.strReq || 0;
  if (req && h.str < req) logMsg(`⚠ ${it.name} needs ${req} Strength (you have ${h.str}).`, "miss");
  render(); saveNow();
}

function usePotion(idx) {
  const h = state.hero, it = h.inventory[idx];
  if (/Healing/.test(it.name)) { h.hp = Math.min(h.maxhp, h.hp + 4); logMsg("Drank Potion of Healing (+4 HP).", "hit"); }
  else if (/Restoration/.test(it.name)) { h.ap = h.maxap; logMsg("Drank Potion of Restoration (AP full).", "hit"); }
  else { logMsg(`Used ${it.name}.`, ""); }
  h.inventory.splice(idx, 1);
  render(); saveNow();
}
function useConsumable(idx, verb) {
  const it = state.hero.inventory[idx];
  if (/Healing/.test(it.name)) { state.hero.hp = Math.min(state.hero.maxhp, state.hero.hp + 8); logMsg("Scroll of Healing (+8 HP).", "hit"); }
  else logMsg(`${verb} ${it.name}.`, "");
  state.hero.inventory.splice(idx, 1);
  render(); saveNow();
}

function spellSection(prof) {
  const h = state.hero;
  const box = el("div", {});
  if (!h.spellbook.length) { box.appendChild(el("div", { class: "note" }, "No spells in spell book.")); }
  h.spellbook.forEach((name) => {
    const s = G.spells.find((x) => x.name === name);
    const mem = h.memorized.includes(name);
    box.appendChild(el("label", { class: "field-inline", style: "margin:3px 0" },
      el("input", { type: "checkbox", style: "width:auto", ...(mem ? { checked: "" } : {}),
        onchange: (e) => {
          if (e.target.checked) {
            if (h.memorized.length >= prof.spells) { e.target.checked = false; alert(`Only ${prof.spells} memorized at a time.`); return; }
            h.memorized.push(name);
          } else h.memorized = h.memorized.filter((x) => x !== name);
          saveNow();
        } }),
      el("span", {}, `${name} `, el("span", { class: "sub" }, `${apLabel(s.ap)}AP ${s.combat ? `R${s.R} D${s.D} H${s.H}` : ""}`))));
  });
  return box;
}

/* ----- dungeon panel ----- */
function dungeonPanel() {
  const d = state.dungeon;
  const p = el("div", { class: "panel" });
  if (!d || !d.active) {
    if (d && !d.active && !state.hero.dead) {
      // between dungeons / cleared
      p.appendChild(el("h2", {}, "Between Dungeons"));
      p.appendChild(el("div", {}, `Tier ${d.tier} dungeon complete — ${d.roomsExplored} rooms explored.`));
      p.appendChild(el("div", { class: "note" }, "Sell unwanted trappings (inventory panel), then descend deeper. Your hero keeps stats, gold, equipped gear, and remaining Fudge Points."));
      p.appendChild(el("div", { class: "btn-row", style: "margin-top:12px" },
        el("button", { class: "btn primary", onclick: advanceTier }, `Descend to Tier ${d.tier + 1} →`)));
      p.appendChild(el("h3", {}, "Sell trappings"));
      p.appendChild(sellList());
      return p;
    }
    p.appendChild(el("h2", {}, "Dungeon"));
    p.appendChild(el("div", { class: "btn-row" },
      el("button", { class: "btn primary", onclick: startDungeonPrompt }, "Enter a Dungeon")));
    return p;
  }

  p.appendChild(el("h2", {}, `Dungeon · ${d.theme}`));
  p.appendChild(el("div", { class: "muted", style: "margin-top:-6px" },
    `Rooms explored: ${d.roomsExplored}  ·  Next: room ${d.roomsExplored + 1}` +
    (d.roomsExplored + 1 >= 30 ? "  · 👑 BOSS" : "")));

  const r = d.currentRoom;
  if (!r || r.finished) {
    p.appendChild(el("div", { class: "btn-row", style: "margin:12px 0" },
      el("button", { class: "btn primary", onclick: generateRoom }, "⚄ Generate Next Room (DUN-GEN)")));
    if (r && r.finished) p.appendChild(el("div", { class: "note" }, "Room finished. Pick a door and generate the next room."));
    return p;
  }

  // current room details
  const rr = el("div", { class: "gen-result" });
  rr.appendChild(el("div", {}, el("span", { class: "k" }, `Room ${r.roomNum}: `), `${r.size} squares, ${r.doors} extra door(s).`));
  const doorPills = el("div", {}, el("span", { class: "k" }, "Doors: "));
  doorPills.appendChild(el("span", { class: "pill unlocked" }, "entry"));
  r.doorStatuses.forEach((s) => doorPills.appendChild(el("span", { class: "pill " + s.toLowerCase() }, s)));
  rr.appendChild(doorPills);
  if (r.special) rr.appendChild(el("div", {}, el("span", { class: "k" }, "Special Room: "), `${r.special.name} — ${r.special.text}`));
  if (r.chests.length) {
    const cp = el("div", {}, el("span", { class: "k" }, "Chests: "));
    r.chests.forEach((c) => cp.appendChild(el("span", { class: "pill " + c.status.toLowerCase() }, c.opened ? "opened" : c.status)));
    rr.appendChild(cp);
  }
  p.appendChild(rr);

  // combat
  if (r.monsters.length) {
    p.appendChild(el("div", { class: "round-banner" }, d.inCombat ? `Combat — round ${d.round}` : "Combat resolved"));
    r.monsters.forEach((mon) => p.appendChild(monsterRow(mon)));
    if (d.inCombat) {
      p.appendChild(el("div", { class: "btn-row", style: "margin-top:8px" },
        el("button", { class: "btn", onclick: monstersAttack }, "👹 Monsters Attack →"),
        el("button", { class: "btn sm", onclick: () => { fleeRoom(); } }, "Flee room")));
    }
  } else {
    p.appendChild(el("div", { class: "note" }, "No monsters in this room."));
  }

  // post-combat actions
  const cleared = r.monsters.every((m) => m.hp <= 0);
  if (cleared || !r.monsters.length) {
    p.appendChild(el("h3", {}, "Loot & finish"));
    const lootRow = el("div", { class: "btn-row" });
    if (r.monsters.length && !r.looted) {
      lootRow.appendChild(el("button", { class: "btn sm", onclick: () => lootCheck() }, "Loot check (slain monsters)"));
    }
    r.chests.forEach((c, i) => {
      if (!c.opened) lootRow.appendChild(el("button", { class: "btn sm", onclick: () => openChest(i) },
        `Open chest ${i + 1}${c.status !== "Unlocked" ? " (" + c.status + ")" : ""}`));
    });
    if (r.special) lootRow.appendChild(el("button", { class: "btn sm", onclick: () => specialRoomLoot(r.special) }, `Use ${r.special.name}`));
    lootRow.appendChild(el("button", { class: "btn sm", onclick: rollTreasureItem }, "+ Roll treasure"));
    p.appendChild(lootRow);
    p.appendChild(el("div", { class: "btn-row", style: "margin-top:10px" },
      el("button", { class: "btn primary", onclick: finishRoom }, "✓ Finish Room")));
  }
  return p;
}

function monsterRow(mon) {
  const pct = mon.hpMax > 0 ? (mon.hp / mon.hpMax) * 100 : 0;
  const dead = mon.hp <= 0;
  const row = el("div", { class: "monster" + (mon.boss ? " boss" : "") + (dead ? " dead" : "") });
  row.appendChild(el("div", { class: "mname" }, mon.boss ? "👑 " + mon.label : mon.label,
    mon.special ? el("div", { class: "mstats" }, mon.special) : null));
  row.appendChild(el("div", { class: "mstats" }, `Def${mon.Def} R${mon.R} M${mon.M} Att${mon.att[0]}-${mon.att[1]} D${mon.D}`));
  if (!dead) {
    row.appendChild(el("div", { class: "minihp" },
      el("div", { class: "bar", style: "height:16px" },
        el("div", { class: "fill hp", style: `width:${pct}%` }),
        el("div", { class: "lbl", style: "font-size:11px" }, `${mon.hp}/${mon.hpMax}`))));
    const acts = el("div", { class: "btn-row" });
    acts.appendChild(el("button", { class: "btn sm", onclick: () => heroAttack(mon) }, "⚔ Attack"));
    // memorized combat spells
    state.hero.memorized.forEach((sn) => {
      const s = G.spells.find((x) => x.name === sn);
      if (s && s.combat) acts.appendChild(el("button", { class: "btn sm", onclick: () => castCombatSpell(sn, mon) }, "✦ " + sn));
    });
    acts.appendChild(el("button", { class: "btn sm", onclick: () => { mon.hp -= 1; if (mon.hp <= 0) killMonster(mon); render(); saveNow(); } }, "−1"));
    row.appendChild(acts);
  } else {
    row.appendChild(el("div", { class: "mstats" }, "slain"));
  }
  return row;
}

function lootCheck() {
  const r = state.dungeon.currentRoom;
  const slain = r.monsters.filter((m) => m.hp <= 0).length;
  r.looted = true;
  const d6 = roll(6);
  if (d6 < slain) { logMsg(`Loot check: d6=${d6} < ${slain} slain — found treasure!`, "gold"); rollTreasureItem(); }
  else logMsg(`Loot check: d6=${d6} (need < ${slain}) — nothing found.`, "");
  render(); saveNow();
}

function openChest(i) {
  const c = state.dungeon.currentRoom.chests[i];
  if (c.status === "Locked") { if (!confirm("This chest is Locked. Open it anyway (assumes you used an ability/item/spell)?")) return; }
  if (c.status === "Trapped") { state.hero.hp -= 1; logMsg("Trapped chest! −1 HP (cannot be mitigated).", "miss"); if (state.hero.hp <= 0) return heroDies(); }
  c.opened = true;
  logMsg(`Opened chest ${i + 1}.`, "gold");
  rollTreasureItem();
}

function specialRoomLoot(sr) {
  const rolls = { Armory: () => { equipRoll(G.weapons, 8, "weapon"); equipRoll(G.armor, 6, null); equipRoll(G.exoticWeapons, 6, "weapon", true); },
    "Alchemy Lab": () => { for (let i = 0; i < 3; i++) { const p = pickByRange(G.potions, roll(8)); pushItem({ kind: "potion", name: p.name, text: p.text }); } },
    Library: () => { for (let i = 0; i < 3; i++) { const s = pickByRange(G.scrolls, roll(8)); pushItem({ kind: "scroll", name: s.name, text: s.text }); } },
    "Arcane Forge": () => { for (let i = 0; i < 2; i++) { const mi = pickByRange(G.magicItems, roll(8)); pushItem({ kind: "magic", name: mi.name, text: mi.text, ...mi }); } },
    "Healing Font": () => { state.hero.hp = state.hero.maxhp; logMsg("Healing Font: HP restored to max.", "hit"); },
    "Altar of Blessing": () => { state.hero.bonusRatingBase = (state.hero.bonusRatingBase || 0) + 1; recomputeBonusRating(); logMsg("Altar of Blessing: +1 Bonus Rating.", "gold"); },
  };
  (rolls[sr.name] || (() => {}))();
  render(); saveNow();
}
function equipRoll(list, die, slot, exotic) {
  const it = list[roll(die) - 1];
  const obj = slot === "weapon" ? { kind: "weapon", exotic: !!exotic, ...it } : { kind: it.type, ...it };
  applyBonusRating(obj); pushItem(obj);
}
function pushItem(it) { applyBonusRating(it); state.hero.inventory.push(it); logMsg(`Found: ${it.name}${brSuffix(it)}.`, "gold"); }

function fleeRoom() {
  if (!confirm("Flee this room? Slain monsters are erased, survivors restored to full HP, no loot, no AP restore. The room stays unexplored.")) return;
  const r = state.dungeon.currentRoom;
  r.monsters = []; r.finished = true; state.dungeon.inCombat = false;
  logMsg(`Fled room ${r.roomNum}. (Pursuit by faster monsters is up to you to adjudicate on the map.)`, "miss");
  render(); saveNow();
}

function sellList() {
  const h = state.hero;
  if (!h.inventory.length) return el("div", { class: "note" }, "Nothing to sell.");
  const ul = el("ul", { class: "itemlist" });
  h.inventory.forEach((it, idx) => ul.appendChild(el("li", {},
    el("span", { class: "grow" }, it.name, el("span", { class: "sub" }, "  " + (itemStatLine(it) || ""))),
    el("button", { class: "btn sm", onclick: () => sellItem(idx) }, "sell"))));
  return ul;
}

/* ----- map panel ----- */
function mapPanel() {
  const d = state.dungeon;
  if (!d || !d.active) return el("div");
  const p = el("div", { class: "panel" });
  p.appendChild(el("h2", {}, "🗺 Map"));
  const tools = [["floor", "Floor"], ["door", "Door 🚪"], ["hero", "Hero 🛡"], ["monster", "Monster 👹"],
    ["treasure", "Chest 📦"], ["num", "Room #"], ["erase", "Erase"]];
  const pal = el("div", { class: "palette" });
  tools.forEach(([id, label]) => pal.appendChild(el("button", {
    class: "btn sm" + (paintTool === id ? " active" : ""),
    onclick: () => { paintTool = id; render(); },
  }, label)));
  p.appendChild(pal);
  p.appendChild(el("div", { class: "note", style: "margin-bottom:8px" },
    "Click squares to paint your dungeon as you explore. Entrance is pre-marked at bottom-center."));

  const grid = el("div", { class: "map-grid", style: `grid-template-columns: repeat(${d.map.w}, 26px)` });
  for (let r = 0; r < d.map.h; r++) {
    for (let c = 0; c < d.map.w; c++) {
      const key = `${r},${c}`;
      const val = d.map.cells[key] || "";
      grid.appendChild(mapCell(key, val));
    }
  }
  p.appendChild(el("div", { class: "map-wrap" }, grid));
  p.appendChild(el("div", { class: "btn-row", style: "margin-top:8px" },
    el("button", { class: "btn sm danger", onclick: () => { if (confirm("Clear the whole map?")) { d.map.cells = {}; render(); saveNow(); } } }, "Clear map")));
  return p;
}

function mapCell(key, val) {
  const cls = ["cell"];
  let txt = "";
  if (["floor"].includes(val)) cls.push("floor");
  else if (val === "hero") { cls.push("hero"); txt = "🛡"; }
  else if (val === "monster") { cls.push("monster"); txt = "👹"; }
  else if (val === "treasure") { cls.push("treasure"); txt = "📦"; }
  else if (val === "door") { cls.push("door"); txt = "🚪"; }
  else if (/^\d+$/.test(val)) { cls.push("floor", "explored"); txt = val; }
  return el("div", { class: cls.join(" "), onclick: () => paintCell(key) }, txt);
}

function paintCell(key) {
  const cells = state.dungeon.map.cells;
  if (paintTool === "erase") delete cells[key];
  else if (paintTool === "num") {
    const n = prompt("Room number:", String(state.dungeon.roomsExplored + (state.dungeon.currentRoom && !state.dungeon.currentRoom.finished ? 1 : 0)));
    if (n) cells[key] = n;
  } else cells[key] = paintTool;
  render(); saveNow();
