function spendFudge(cost, effect) {
  const h = state.hero;
  h.fudgeSpent = (h.fudgeSpent || 0) + cost;
  recomputeFudge();
  if (effect === "str") h.str += 1;
  else if (effect === "agi") h.agi += 1;
  else if (effect === "wil") { h.wil += 1; h.maxap = deriveMaxAP(h); }
  else if (effect === "hp") { h.maxhp += 3; h.hp += 3; }
  logMsg(`Spent ${cost} Fudge Point(s)${effect !== "track-fudge" ? " for a permanent boost" : ""}.`, "gold");
  closeModal(); render(); saveNow();
}

