input.new_string:
/* ----- map panel -----
 * Tiles hold room contents (floor/hero/monster/chest/room#); doors sit on the
 * wall SEGMENTS between tiles. The grid is interleaved: tile cells separated by
 * thin edge cells, plus a full outer perimeter of edges (for exterior doors). */
const entranceEdge = (w, h) => `h:${h},${Math.floor(w / 2)}`; // south wall of bottom-center square

function mapPanel() {
  const d = state.dungeon;
  if (!d || !d.active) return el("div");
  if (!d.map.edges) d.map.edges = {};                 // migrate older maps
  const W = d.map.w, H = d.map.h;
  const p = el("div", { class: "panel" });
  p.appendChild(el("h2", {}, "🗺 Map"));
  const tools = [["floor", "Floor"], ["door", "Door 🚪"], ["hero", "Hero 🛡"], ["monster", "Monster 👹"],
    ["treasure", "Chest 📦"], ["num", "Room #"], ["erase", "Erase"]];
  const pal = el("div", { class: "palette" });
  tools.forEach(([id, label]) => pal.appendChild(el("button", {
    class: "btn sm" + (paintTool === id ? " active" : ""),
    onclick: () => { paintTool = id; render(); },
  }, label)));
  p.appendChild(pal);
  p.appendChild(el("div", { class: "note", style: "margin-bottom:8px" },
    paintTool === "door"
      ? "Click the wall segments between (or around) squares to place doors. Entrance is pre-marked at bottom-center."
      : "Click squares to paint room contents. Pick the Door tool to place doors on wall segments."));

  // interleaved grid: cols 0..2W (even = edge/post 8px, odd = tile 26px); rows 0..2H
  const cols = 2 * W + 1, rowsN = 2 * H + 1;
  const tpl = (n) => Array.from({ length: n }, (_, i) => (i % 2 === 0 ? "8px" : "26px")).join(" ");
  const grid = el("div", { class: "map-grid", style: `grid-template-columns:${tpl(cols)};grid-template-rows:${tpl(rowsN)}` });

  for (let gr = 0; gr < rowsN; gr++) {
    for (let gc = 0; gc < cols; gc++) {
      const rOdd = gr % 2 === 1, cOdd = gc % 2 === 1;
      if (rOdd && cOdd) {                              // tile
        const r = (gr - 1) / 2, c = (gc - 1) / 2;
        grid.appendChild(mapCell(`${r},${c}`, d.map.cells[`${r},${c}`] || ""));
      } else if (!rOdd && cOdd) {                      // horizontal wall segment
        grid.appendChild(edgeCell(`h:${gr / 2},${(gc - 1) / 2}`, "h"));
      } else if (rOdd && !cOdd) {                       // vertical wall segment
        grid.appendChild(edgeCell(`v:${(gr - 1) / 2},${gc / 2}`, "v"));
      } else {                                          // corner post
        grid.appendChild(el("div", { class: "post" }));
      }
    }
  }
  p.appendChild(el("div", { class: "map-wrap" }, grid));
  p.appendChild(el("div", { class: "btn-row", style: "margin-top:8px" },
    el("button", { class: "btn sm danger", onclick: () => {
      if (confirm("Clear the whole map? (The entrance door is kept.)")) {
        d.map.cells = {}; d.map.edges = {}; d.map.edges[entranceEdge(W, H)] = "door";
        render(); saveNow();
      } } }, "Clear map")));
  return p;
}

function mapCell(key, val) {
  const cls = ["cell"];
  let txt = "";
  if (val === "floor") cls.push("floor");
  else if (val === "hero") { cls.push("hero"); txt = "🛡"; }
  else if (val === "monster") { cls.push("monster"); txt = "👹"; }
  else if (val === "treasure") { cls.push("treasure"); txt = "📦"; }
  else if (/^\d+$/.test(val)) { cls.push("floor", "explored"); txt = val; }
  if (paintTool !== "door") cls.push("clickable");
  return el("div", { class: cls.join(" "), onclick: () => { if (paintTool !== "door") paintCell(key); } }, txt);
}

function edgeCell(key, orient) {
  const isDoor = state.dungeon.map.edges[key] === "door";
  const cls = ["edge", orient];
  if (isDoor) cls.push("door");
  if (paintTool === "door" || paintTool === "erase") cls.push("clickable");
  return el("div", { class: cls.join(" "),
    onclick: () => { if (paintTool === "door" || paintTool === "erase") paintEdge(key); } });
}

function paintCell(key) {
  const cells = state.dungeon.map.cells;
  if (paintTool === "erase") delete cells[key];
  else if (paintTool === "num") {
    const n = prompt("Room number:", String(state.dungeon.roomsExplored + (state.dungeon.currentRoom && !state.dungeon.currentRoom.finished ? 1 : 0)));
    if (n) cells[key] = n;
  } else if (paintTool !== "door") cells[key] = paintTool;
  render(); saveNow();
}

function paintEdge(key) {
  const edges = state.dungeon.map.edges;
  if (paintTool === "erase" || edges[key] === "door") delete edges[key]; // toggle off / erase
  else edges[key] = "door";
  render(); saveNow();
}

.cell.explored { color: var(--muted); font-size: 11px; }
.cell.clickable { cursor: pointer; }
/* wall segments between/around tiles — doors live here, not on tiles */
.post { width: 8px; height: 8px; }
.edge { background: transparent; }
.edge.clickable { cursor: pointer; }
.edge.clickable:hover { background: rgba(217, 164, 65, .4); border-radius: 2px; }
.edge.door { background: var(--gold); border-radius: 2px; box-shadow: 0 0 3px rgba(217,164,65,.6); }
.edge.h.door { align-self: center; height: 5px; }
.edge.v.door { justify-self: center; width: 5px; }

