/* ----- monster instances & encounter building ----- */
function addMonsterInstance(room, mon, boss) {
  const inst = { ...mon, uid: room.nextMonId++, hpMax: mon.HP, hp: mon.HP,
    boss: !!boss, label: baseName(mon.name) };
  room.monsters.push(inst);
  return inst;
}
// give A/B/C suffixes only when more than one of the same base name is present
function relabelMonsters(room) {
  const counts = {};
  room.monsters.forEach((m) => { counts[baseName(m.name)] = (counts[baseName(m.name)] || 0) + 1; });
  const seen = {};
  room.monsters.forEach((m) => {
    const b = baseName(m.name);
    if (counts[b] > 1) { seen[b] = (seen[b] || 0); m.label = `${b} ${String.fromCharCode(65 + seen[b])}`; seen[b]++; }
    else m.label = b;
  });
}

// full catalog for the "add enemy" picker: this dungeon's package + summons + everything in the manual
function enemyCatalog() {
  const out = [], byName = {};
  const push = (mon, group) => { if (!byName[mon.name + group]) { byName[mon.name + group] = 1; out.push({ group, mon }); } };
  const pkg = state.dungeon?.package;
  if (pkg) pkg.monsters.forEach((mn) => push(mn, "This dungeon"));
  (G.summons || []).forEach((mn) => push(mn, "Summons"));
  G.monsterManual.forEach((p) => p.monsters.forEach((mn) => push(mn, `Tier ${p.tier} · ${p.theme}`)));
  return out;
}

function addEnemy(monDef, qty) {
  const d = state.dungeon, r = d.currentRoom;
  if (!r) return;
  const boss = / \(Boss\)/.test(monDef.name);
  for (let i = 0; i < Math.max(1, qty); i++) addMonsterInstance(r, monDef, boss);
  relabelMonsters(r);
  d.inCombat = true;
  logMsg(`Added ${qty}× ${baseName(monDef.name)} to the encounter.`, "");
  render(); saveNow();
}

function removeEnemy(uid) {
  const r = state.dungeon.currentRoom;
  r.monsters = r.monsters.filter((m) => m.uid !== uid);
  relabelMonsters(r);
  if (!r.monsters.some((m) => m.hp > 0)) state.dungeon.inCombat = false;
  render(); saveNow();
}

function clearEncounter() {
  const r = state.dungeon.currentRoom;
  if (!r || !confirm("Remove all enemies from this encounter?")) return;
  r.monsters = []; state.dungeon.inCombat = false;
  render(); saveNow();
}

// re-roll the monster COUNT for this room's depth and rebuild the encounter
function rerollEncounter() {
  const d = state.dungeon, r = d.currentRoom;
  if (!r) return;
  const { mon, boss } = monsterForRoom(d.roomsExplored);
  let count = r.isBossRoom ? 1 : tableLookup(G.dungen.monsters, roll(8));
  if (!r.isBossRoom && mon.special && /\+2 to any # Monsters result of 1 or more/.test(mon.special) && count >= 1) count += 2;
  r.monsters = []; r.nextMonId = 0; r.monsterType = baseName(mon.name); r.monsterCount = count;
  for (let i = 0; i < count; i++) addMonsterInstance(r, mon, boss);
  relabelMonsters(r);
  d.inCombat = count > 0; d.round = count > 0 ? 1 : 0;
  logMsg(`Re-rolled encounter: ${count || "no"} ${baseName(mon.name)}${count === 1 ? "" : "s"}.`, "gold");
  render(); saveNow();
}

function applyDamageToMon(mon, amount) {
  if (!amount) return;
  mon.hp -= amount;
  logMsg(`${mon.label} takes ${amount} damage.`, "hit");
  if (mon.hp <= 0) killMonster(mon);
  render(); saveNow();
}
function healMon(mon, amount) {
  mon.hp = Math.min(mon.hpMax, mon.hp + amount);
  render(); saveNow();
}

