/* ----- placement checklist: the assets to put on the map for this room ----- */
function placementChecklist(r) {
  const box = el("div", { class: "checklist" });
  box.appendChild(el("div", { class: "cl-head" }, `📋 Place for Room ${r.roomNum}` + (r.isBossRoom ? "  👑 BOSS" : "")));
  const item = (txt, sub) => el("div", { class: "cl-item" },
    el("span", { class: "cl-box" }, "▢"),
    el("span", {}, txt, sub ? el("span", { class: "sub" }, "  " + sub) : null));

  box.appendChild(item(`Draw a room of ${r.size} connected squares.`));

  // doors: entry + the rolled extras (with lock/trap status)
  const doorParts = ["1 entry (unlocked)"];
  const counts = { Unlocked: 0, Locked: 0, Trapped: 0 };
  r.doorStatuses.forEach((s) => counts[s]++);
  Object.entries(counts).forEach(([k, n]) => { if (n) doorParts.push(`${n} ${k.toLowerCase()}`); });
  box.appendChild(item(`Place ${r.doors} extra door${r.doors === 1 ? "" : "s"} on wall segments.`, doorParts.join(", ")));

  // monsters
  if (r.monsters.length) {
    const byType = {};
    r.monsters.forEach((m) => { byType[baseName(m.name)] = (byType[baseName(m.name)] || 0) + 1; });
    const desc = Object.entries(byType).map(([n, c]) => `${c}× ${n}`).join(", ");
    box.appendChild(item(`Place ${desc}.`, "only 1 monster per square adjacent to the hero — track HP below"));
  } else {
    box.appendChild(item("No monsters in this room."));
  }

  // treasure / special room
  if (r.special) box.appendChild(item(`Mark this a Special Room: ${r.special.name}.`, r.special.text));
  if (r.chests.length) {
    const cc = { Unlocked: 0, Locked: 0, Trapped: 0 };
    r.chests.forEach((c) => cc[c.status]++);
    const parts = Object.entries(cc).filter(([, n]) => n).map(([k, n]) => `${n} ${k.toLowerCase()}`);
    box.appendChild(item(`Place ${r.chests.length} treasure chest${r.chests.length === 1 ? "" : "s"}.`, parts.join(", ")));
  } else if (!r.special && !r.isBossRoom) {
    box.appendChild(item("No treasure chests."));
  }
  box.appendChild(el("div", { class: "cl-item" }, el("span", { class: "cl-box" }, "▢"),
    el("span", {}, "Place the hero 🛡 just inside the door you entered through.")));
  return box;
}

/* ----- combat manager ----- */
function combatManager(d, r) {
  const box = el("div", {});
  const alive = r.monsters.filter((m) => m.hp > 0).length;
  box.appendChild(el("h3", {}, "⚔ Combat Manager",
    el("span", { class: "sub" }, r.monsters.length ? `  ${alive} of ${r.monsters.length} standing` : "  no enemies")));

  if (r.monsters.length) {
    box.appendChild(el("div", { class: "round-banner" },
      d.inCombat ? `Round ${d.round}` : (alive ? "Paused" : "Encounter cleared")));
    r.monsters.forEach((mon) => box.appendChild(monsterRow(mon)));
  } else {
    box.appendChild(el("div", { class: "note" }, "No enemies. Add reinforcements/summons below, or re-roll the encounter."));
  }

  // hero-side & round controls
  const ctrl = el("div", { class: "btn-row", style: "margin-top:8px" });
  if (alive) {
    ctrl.appendChild(el("button", { class: "btn", onclick: monstersAttack }, "👹 Monsters Attack →"));
    ctrl.appendChild(el("button", { class: "btn sm", onclick: fleeRoom }, "Flee room"));
  }
  ctrl.appendChild(el("button", { class: "btn sm", onclick: rerollEncounter }, "⟳ Re-roll encounter"));
  if (r.monsters.length) ctrl.appendChild(el("button", { class: "btn sm danger", onclick: clearEncounter }, "Clear"));
  box.appendChild(ctrl);

  // add enemy / summon
  const cat = enemyCatalog();
  const sel = el("select", { id: "addEnemySel", style: "max-width:280px" });
  let lastGroup = null;
  cat.forEach((e, i) => {
    if (e.group !== lastGroup) { lastGroup = e.group; sel.appendChild(el("option", { disabled: "", value: "" }, `— ${e.group} —`)); }
    sel.appendChild(el("option", { value: String(i) },
      `${baseName(e.mon.name)} (Def${e.mon.Def} HP${e.mon.HP})`));
  });
  // default selection to first real option
  const firstReal = cat.findIndex(() => true);
  box.appendChild(el("div", { class: "add-enemy" },
    el("span", { class: "sub" }, "Add reinforcements / summons:"),
    sel,
    el("input", { type: "number", id: "addEnemyQty", value: "1", min: "1", style: "width:54px" }),
    el("button", { class: "btn sm", onclick: () => {
      const idx = parseInt($("#addEnemySel").value, 10);
      if (isNaN(idx) || !cat[idx]) { alert("Pick a monster to add."); return; }
      const qty = Math.max(1, parseInt($("#addEnemyQty").value || "1", 10));
      addEnemy(cat[idx].mon, qty);
    } }, "+ Add")));
  return box;
}

function monsterRow(mon) {
  const pct = mon.hpMax > 0 ? Math.max(0, (mon.hp / mon.hpMax) * 100) : 0;
  const dead = mon.hp <= 0;
  const row = el("div", { class: "monster" + (mon.boss ? " boss" : "") + (dead ? " dead" : "") });
  row.appendChild(el("div", { class: "mname" }, mon.boss ? "👑 " + mon.label : mon.label,
    el("div", { class: "mstats" }, `Def${mon.Def} R${mon.R} M${mon.M} Att${mon.att[0]}-${mon.att[1]} D${mon.D}`),
    mon.special ? el("div", { class: "mstats" }, mon.special) : null));
  if (!dead) {
    row.appendChild(el("div", { class: "minihp" },
      el("div", { class: "bar", style: "height:16px" },
        el("div", { class: "fill hp", style: `width:${pct}%` }),
        el("div", { class: "lbl", style: "font-size:11px" }, `${mon.hp}/${mon.hpMax}`))));
    const acts = el("div", { class: "btn-row" });
    acts.appendChild(el("button", { class: "btn sm", onclick: () => heroAttack(mon) }, "⚔ Attack"));
    state.hero.memorized.forEach((sn) => {
      const s = G.spells.find((x) => x.name === sn);
      if (s && s.combat) acts.appendChild(el("button", { class: "btn sm", onclick: () => castCombatSpell(sn, mon) }, "✦ " + sn));
    });
    // free-form damage input
    const dmgIn = el("input", { type: "number", placeholder: "dmg", style: "width:52px" });
    const applyDmg = () => { const v = parseInt(dmgIn.value || "0", 10); if (v) { applyDamageToMon(mon, v); } };
    dmgIn.addEventListener("keydown", (e) => { if (e.key === "Enter") applyDmg(); });
    acts.appendChild(dmgIn);
    acts.appendChild(el("button", { class: "btn sm", onclick: applyDmg }, "hit"));
    acts.appendChild(el("button", { class: "btn sm", onclick: () => applyDamageToMon(mon, 1) }, "−1"));
    acts.appendChild(el("button", { class: "btn sm", title: "remove from encounter", onclick: () => removeEnemy(mon.uid) }, "✕"));
    row.appendChild(acts);
  } else {
    row.appendChild(el("div", { class: "btn-row" },
      el("div", { class: "mstats" }, "slain"),
      el("button", { class: "btn sm", title: "revive (undo)", onclick: () => healMon(mon, mon.hpMax) }, "↺"),
      el("button", { class: "btn sm", onclick: () => removeEnemy(mon.uid) }, "✕")));
  }
  return row;
}

