function healMon(mon, amount) {
  mon.hp = Math.min(mon.hpMax, mon.hp + amount);
  if (mon.hp > 0 && mon.counted) {              // revived: undo the kill tally
    mon.counted = false;
    state.dungeon.monstersSlainDungeon = Math.max(0, state.dungeon.monstersSlainDungeon - 1);
    state.hero.monstersSlainTotal = Math.max(0, state.hero.monstersSlainTotal - 1);
    recomputeFudge();
  }
  render(); saveNow();
}

