/* draggable + collapsible dock; position & collapsed state persist in localStorage */
function setupDockControls() {
  const dock = $("#dock"), header = $("#dockHeader"), minBtn = $("#dockMin");
  if (!dock || !header) return;

  const applyMin = (min) => {
    dock.classList.toggle("minimized", min);
    minBtn.textContent = min ? "▸" : "▾";
    try { localStorage.setItem("pd_dock_min", min ? "1" : "0"); } catch (e) {}
  };
  const applyPos = (p) => {
    if (!p) return;
    dock.style.left = p.left + "px"; dock.style.top = p.top + "px";
    dock.style.right = "auto"; dock.style.bottom = "auto";
  };

  // restore saved state
  try {
    applyMin(localStorage.getItem("pd_dock_min") === "1");
    const saved = JSON.parse(localStorage.getItem("pd_dock_pos") || "null");
    applyPos(saved);
  } catch (e) {}

  minBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    applyMin(!dock.classList.contains("minimized"));
  });

  // drag by the header (ignore clicks that start on the minimize button)
  let dragging = false, ox = 0, oy = 0;
  header.addEventListener("pointerdown", (e) => {
    if (e.target.closest(".dock-btn")) return;
    dragging = true;
    const rect = dock.getBoundingClientRect();
    ox = e.clientX - rect.left; oy = e.clientY - rect.top;
    dock.style.left = rect.left + "px"; dock.style.top = rect.top + "px";
    dock.style.right = "auto"; dock.style.bottom = "auto";
    header.setPointerCapture(e.pointerId);
    e.preventDefault();
  });
  header.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    const w = dock.offsetWidth, h = dock.offsetHeight;
    const left = Math.max(0, Math.min(window.innerWidth - w, e.clientX - ox));
    const top = Math.max(0, Math.min(window.innerHeight - h, e.clientY - oy));
    dock.style.left = left + "px"; dock.style.top = top + "px";
  });
  const endDrag = (e) => {
    if (!dragging) return;
    dragging = false;
    try { header.releasePointerCapture(e.pointerId); } catch (err) {}
    try {
      localStorage.setItem("pd_dock_pos", JSON.stringify({
        left: parseInt(dock.style.left, 10), top: parseInt(dock.style.top, 10) }));
    } catch (err) {}
  };
  header.addEventListener("pointerup", endDrag);
  header.addEventListener("pointercancel", endDrag);
}

