function refRules(p) {
  p.appendChild(el("div", { class: "note", style: "margin-bottom:6px" },
    "The complete Pocket Dungeon 2.0 rules. Jump to the Combat section for attack resolution, monster actions, and armor."));
  GAME.rules.forEach((sec) => {
    const box = el("div", { class: "rules-sec" + (sec.combat ? " combat" : "") });
    box.appendChild(el("h3", {}, (sec.combat ? "⚔ " : "") + sec.title));
    sec.blocks.forEach((b) => {
      if (typeof b === "string") box.appendChild(el("p", { class: "rule-p" }, b));
      else if (b.h) box.appendChild(el("h4", { class: "rule-h" }, b.h));
      else if (b.ul) box.appendChild(el("ul", { class: "rule-ul" }, ...b.ul.map((i) => el("li", {}, i))));
      else if (b.dl) {
        const dl = el("div", { class: "rule-dl" });
        b.dl.forEach(([t, d]) => dl.appendChild(el("div", { class: "rule-dt" },
          el("span", { class: "term" }, t), el("span", {}, " — " + d))));
        box.appendChild(dl);
      }
      else if (b.ex) box.appendChild(el("div", { class: "rule-ex" }, b.ex));
      else if (b.note) box.appendChild(el("div", { class: "note" }, b.note));
    });
    p.appendChild(box);
  });
}

